const sample = {
  "demo": true,
  "name": "Leila Haddad",
  "email": "leila@example.com",
  "role": "Automation engineer",
  "years": 5,
  "workAuth": true,
  "resumeText": "Five years building JavaScript services, SQL reporting, and n8n workflows for HubSpot teams.",
  "start": "2026-12-04T16:00:00.000Z",
  "end": "2026-12-04T16:30:00.000Z",
  "status": "booked",
  "phone": "+15555550155",
  "title": "Interview with Leila Haddad"
};
const incoming = $input.first()?.json ?? {};
const provided = Object.keys(incoming).filter((key) => incoming[key] !== undefined && incoming[key] !== null && incoming[key] !== '');
const base = provided.length ? { ...sample, ...incoming } : { ...sample };
const flag = incoming.demo;
base.demo = !(flag === false || flag === 'false' || flag === 0 || flag === '0');
return [{ json: base }];

const item = $input.first().json;
const produced = (() => {

const start = Date.parse(item.start || item.startsAt || '');
const status = String(item.status || 'booked').toLowerCase();
const offsets = ['24h'];
const hours = { '24h': 24, '2h': 2, '1h': 1, '15m': 0.25 };
const reminders = offsets.map((offset) => ({
  offset,
  sendAt: Number.isNaN(start) ? null : new Date(start - (hours[offset] || 1) * 3600 * 1000).toISOString(),
  channel: item.phone ? 'sms' : 'email',
}));
let route = 'schedule';
if (status === 'canceled' || status === 'cancelled') route = 'reschedule';
else if (status === 'no-show') route = 'recover';
else if (Number.isNaN(start)) route = 'missing-time';
const record = {
  email: item.email || '',
  phone: item.phone || '',
  to: item.phone || '',
  title: item.title || 'Appointment',
  start: item.start || item.startsAt || '',
  end: item.end || '',
  status,
  reminders,
  message: 'Reminder: ' + (item.title || 'your appointment') + ' at ' + (item.start || item.startsAt || 'the scheduled time') + '.',
};
return {
  summary: record.title + ' for ' + (record.email || record.phone || 'the guest') + ' is ' + route + '.',
  route,
  record,
  slackText: route.toUpperCase() + ' — ' + record.title + ' (' + (record.start || 'unscheduled') + ')',
  actions: reminders.map((reminder) => ({ app: reminder.channel, operation: 'remind', payload: reminder })),
};

})();
if (!produced || typeof produced.summary !== 'string' || !produced.summary.trim()) {
  throw new Error('Apply rules must return a summary string');
}
return [{
  json: {
    ...item,
    ...produced,
    demo: item.demo !== false,
  },
}];

const item = $input.first().json;
return [{
  json: {
    demo: true,
    status: 'demo_ready',
    workflow: 'interview-schedule-from-application',
    summary: item.summary,
    route: item.route ?? null,
    record: item.record ?? {},
    actions: item.actions ?? [],
    slackText: item.slackText ?? item.summary,
    notes: 'Demo mode did not call external apps. Send {"demo": false} after placeholder credentials are replaced.',
  },
}];
